import glob, os, re, hashlib
def key(p):
    b=os.path.basename(p)
    m=re.match(r'(?:ws)?(\d+)_(?:item)?(\d+)', b)
    return (m.group(1), m.group(2)) if m else (b,)
def sizes(pat):
    d={}
    for p in glob.glob(pat):
        d.setdefault(key(p), []).append((os.path.getsize(p), p))
    return d
live=sizes('live/*.txt'); test=sizes('carved_test/*.txt'); deep=sizes('carved_deep/*.txt')
print("keys: live",len(live),"carved_test",len(test),"carved_deep",len(deep))
